      $sgl_search = &quot;t.topic_title LIKE &#039;%&quot; . addslashes($title) . &quot;%&#039;&quot;;

      $sql = &quot;SELECT t.*, u.user_id, u.username, f.forum_id, f.forum_name, tor.size
            FROM &quot;. BB_TOPICS .&quot; t, &quot;. BB_USERS .&quot; u, &quot;. BB_FORUMS .&quot; f, &quot;. BB_BT_TORRENTS .&quot; tor
