            AND t.forum_id = f.forum_id
            AND t.topic_poster = u.user_id
            GROUP BY t.topic_title LIMIT 0,8&quot;;
      if ( !($result = DB()-&gt;sql_query($sql)) )
      {
          bb_die(&quot;Could not get main information for similar topics&quot;);
      }
      $similar = array();
      while ( $row = DB()-&gt;sql_fetchrow($result) )
      {
          $similar[] = $row;
      }
