            $poster_username = &#039;&lt;a class=&quot;genmed&quot; href=&quot;&#039;. $poster_url .&#039;&quot;&gt;&#039;. $similar[$i][&#039;username&#039;] .&#039;&lt;/a&gt;&#039;;

